INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (2.1, 3001, 100, 130011, "2030/01/01 14:59:59", "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", "ヤマト", 3001100, "2024/10/31 12:00:00", 1, 0, -416.5, 2);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (5.68, 3001, 101, 130011, "2030/01/01 14:59:59", "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", "ヤマト", 3001101, "2024/10/31 12:00:00", 4, 0, -416.5, 2);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (0, 3001, 102, 130011, "2030/01/01 14:59:59", "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", "ヤマト", 3001102, "2024/10/31 12:00:00", 1, 0, -416.5, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (0, 3002, 100, 130211, "2030/01/01 14:59:59", "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", "フブキ", 3002100, "2024/10/31 12:00:00", 1, 0, -416.5, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (0, 3002, 101, 130211, "2030/01/01 14:59:59", "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", "フブキ", 3002101, "2024/10/31 12:00:00", 1, 0, -416.5, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (8.53, 3002, 102, 130211, "2030/01/01 14:59:59", "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", "フブキ", 3002102, "2024/10/31 12:00:00", 5, 0, -416.5, 2);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (5.67, 3002, 103, 130211, "2030/01/01 14:59:59", "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", "フブキ", 3002103, "2024/10/31 12:00:00", 7, 0, -416.5, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (0, 3002, 104, 130211, "2030/01/01 14:59:59", "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", "フブキ", 3002104, "2024/10/31 12:00:00", 1, 0, -416.5, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (0, 3004, 300, 130211, "2030/01/01 14:59:59", "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", "フブキ", 3002300, "2024/10/31 12:00:00", 3, 0, -416.5, 3);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (0, 3005, 301, 130211, "2030/01/01 14:59:59", "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", "フブキ", 3002400, "2024/10/31 12:00:00", 7, 0, -416.5, 7);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (4.4, 3003, 200, 130211, "2030/01/01 14:59:59", "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", "フブキ", 3003200, "2024/10/31 12:00:00", 2, 0, -416.5, 1);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (0, 3003, 201, 130211, "2030/01/01 14:59:59", "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", "フブキ", 3003201, "2024/10/31 12:00:00", 7, 0, -416.5, 7);
INSERT INTO `v1_3a868333e590ec7db565730bc0ff768257a7f4dd3fcec62545e27e0fde76e5fc` VALUES (5.6, 3003, 202, 130211, "2030/01/01 14:59:59", "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", "フブキ", 3003202, "2024/10/31 12:00:00", 1, 0, -416.5, 2);
